import json,pathlib,collections
out=[]
def group(code,theme,title,url,items,topic=None):
 for question,answer,wrong,explanation in items:
  n=241+len(out);pos=(n*3+1)%4;options=list(wrong);options.insert(pos,answer)
  out.append(dict(id=f'q{n:03}',theme=theme,question=question,options=options,correct=pos,explanation=explanation,code=code,topic=topic or ('Gastronomie' if theme=='Gastronomie' else 'Personnalités marquantes'),sources=[dict(title=title,url=url)],verified='2026-11-15'))
